def second_largest(xs: list[int]) -> int:
    unique_values = set()
    for x in xs:
        if x != float('inf'):
            unique_values.add(x)

    sorted_unique_values = sorted(unique_values, reverse=True)
    return sorted_unique_values[1] if len(sorted_unique_values) > 1 else None

