from typing import List, Tuple

def merge_intervals(xs: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if len(xs) <= 1:
        return xs

    # Sort intervals based on their start time
    xs.sort(key=lambda x: x[0])

    merged = [xs[0]]
    for i in range(1, len(xs)):
        last_merged_end = merged[-1][1]

        # If current interval overlaps with the last merged interval
        if xs[i][0] <= last_merged_end:
            merged[-1] = (merged[-1][0], max(last_merged_end, xs[i][1]))
        else:
            merged.append(xs[i])

    return merged

